import random

def play_game():
    """Plays a single game of Rock, Paper, Scissors against the user."""

    # Define the possible choices
    choices = ["rock", "paper", "scissors"]

    # Generate a random choice for the computer
    computer_choice = random.choice(choices)

    # Get the user's choice
    user_choice = input("Enter your choice (rock, paper, scissors): ").lower()

    # Compare the choices and print the result
    if user_choice == "rock":
        if computer_choice == "paper":
            print(f"Computer chose paper. You lose!")
        elif computer_choice == "scissors":
            print(f"Computer chose scissors. You win!")
        else:
            print(f"Computer chose {computer_choice}. It's a tie!")
    elif user_choice == "paper":
        if computer_choice == "rock":
            print(f"Computer chose rock. You win!")
        elif computer_choice == "scissors":
            print(f"Computer chose scissors. You lose!")
        else:
